// MemberCheck decides whether a membership change may happen. It gets the member as they are now and whether they are the
// organization's only owner, and returns an error to refuse the change. It runs under the store's lock, so its decision
// holds for the change that follows.
type MemberCheck func(cur Member, onlyOwner bool) error

// SetMemberRole changes a member's role.
func (s *Store) SetMemberRole(orgID, userID string, role Role) (Member, error) {
	return s.ChangeMemberRole(orgID, userID, role, nil)
}

// ChangeMemberRole changes a member's role if check allows it (nil: always). Demoting an organization's only owner is
// ErrLastOwner.
func (s *Store) ChangeMemberRole(orgID, userID string, role Role, check MemberCheck) (Member, error) {
	if !role.Valid() {
		return Member{}, invalid("unknown role %q", role)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	m, ok := s.members[k]
	if !ok {
		return Member{}, ErrNotFound
	}
	onlyOwner := m.Role == RoleOwner && s.ownerCount(orgID) == 1
	if check != nil {
		if err := check(m, onlyOwner); err != nil {
			return Member{}, err
		}
	}
	if onlyOwner && role != RoleOwner {
		return Member{}, ErrLastOwner
	}
	m.Role = role
	s.members[k] = m
	return m, nil
}

